VAR
    Overload_Trip_Latched : BOOL;
END_VAR

// 3-second delay timer for current exceeding 51.9 A (1.25 * 41.5 A)
Overload_Timer(IN := Motor_Running AND (Motor_Current > 51.9), PT := T#3S);

// Latch the overload trip condition when timer expires
IF Overload_Timer.Q THEN
    Overload_Trip_Latched := TRUE;
END_IF;

// Clear latched trip on rising edge of Fault_Reset
IF Fault_Reset THEN
    Overload_Trip_Latched := FALSE;
END_IF;

// Drive the Overload_Alarm output
Overload_Alarm := Overload_Trip_Latched;

// Motor_Stop command is active if there is an active/latched overload trip or normal stop requested
Motor_Stop := Overload_Trip_Latched OR NOT Start_Command;

